import{_ as o,o as c,c as d,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/INSERT.md","filePath":"manual-zh/INSERT.md","lastUpdated":1785684581000}'),n={name:"manual-zh/INSERT.md"};function t(r,e,p,s,E,T){return c(),d("div",null,[...e[0]||(e[0]=[a(`<h3 id="_17-16-insert" tabindex="-1">17.16 INSERT <a class="header-anchor" href="#_17-16-insert" aria-label="Permalink to &quot;17.16 INSERT&quot;">​</a></h3><pre><code>     INSERT [FILE=]’file_name’
        [CD={NO,YES}]
        [ERROR={CONTINUE,STOP}]
        [SYNTAX={BATCH,INTERACTIVE}]
        [ENCODING={LOCALE, ’charset_name’}].
</code></pre><p><code>INSERT</code> 与 <code>INCLUDE</code>（见 <a href="./INCLUDE">INCLUDE</a>）类似，但更灵活一些。它使命令处理器读取一个文件，就好像它被嵌入在当前命令文件中一样。</p><p>如果指定 <code>CD=YES</code>，则在包含文件之前，当前目录会变为被包含文件所在的目录。默认设置为 ‘CD=NO’。注意，此目录会保持为当前目录，直到被显式更改（通过 <code>CD</code> 命令，或带有 ‘CD=YES’ 选项的后续 <code>INSERT</code> 命令）。即使被包含文件处理完毕，它也不会恢复为原来的设置。</p><p>如果指定 <code>ERROR=STOP</code>，则在被插入文件中遇到的错误会导致处理立即停止。否则处理在下一个命令处继续。默认设置为 <code>ERROR=CONTINUE</code>。</p><p>如果指定 <code>SYNTAX=INTERACTIVE</code>，则包含文件中的语法必须符合交互式语法约定。见 <a href="./Syntax-Variants">Syntax Variants</a>。默认设置为 <code>SYNTAX=BATCH</code>。</p><p><code>ENCODING</code> 可选地指定被包含文件使用的字符集。其参数不区分大小写，必须采用以下形式之一：</p><p><code>LOCALE</code></p><p>系统区域设置使用的编码，或由 <code>SET</code> 命令覆盖（见 <a href="./SET">SET</a>）。在 GNU/Linux 和其他类 Unix 系统上，环境变量（<em>例如</em> <code>LANG</code> 或 <code>LC_ALL</code>）决定系统区域设置。</p><p>charset_name</p><p>IANA 在 <a href="http://www.iana.org/assignments/character-sets" target="_blank" rel="noreferrer">http://www.iana.org/assignments/character-sets</a> 列出的字符集名称之一。一些示例是 <code>ASCII</code>（美国）、<code>ISO-8859-1</code>（西欧）、<code>EUC-JP</code>（日本）和 <code>windows-1252</code>（Windows）。并非所有系统都支持所有字符集。</p><p><code>Auto,encoding</code></p><p>自动检测语法文件是否以 Unicode 编码（如 UTF-8、UTF-16 或 UTF-32）编码。如果不是，则 PSPP 通常假定文件以 encoding（IANA 字符集名称）编码。但是，如果 encoding 为 UTF-8，且语法文件不是有效的 UTF-8，PSPP 则假定文件以 <code>windows-1252</code> 编码。</p><p>为获得最佳结果，encoding 应为 ASCII 兼容编码（最常见的区域设置编码都是 ASCII 兼容的），因为非 ASCII 兼容的编码无法与 UTF-8 自动区分。</p><p><code>Auto</code><code>Auto,Locale</code></p><p>如上所述的自动检测，默认编码取自系统区域设置或 <code>SET LOCALE</code> 的设置。</p><p>当未指定 ENCODING 时，默认值取自 --syntax-encoding 命令选项（如果已指定），否则为 <code>Auto</code>。</p>`,17)])])}const I=o(n,[["render",t]]);export{i as __pageData,I as default};
